INSERT INTO `blogs` VALUES ('3','1','193','2006-09-27 17:28:00','2','MCS 1.58 angefangen','1','<p>Wie bei jeder neuen Version fallen Fehler auf.<br /><br /><br />So auch bei dieser Version.<br /><br /><br />Nun Ideen sind auch neue dazugekommen und ich denke mir fällt auch noch was ein.</p><p><strong>Todolist:</strong><br /><br /></p><p><a href=\"https://www.marblefx.net/home/infos/show/24\">Hier</a></p><p><strong>Buglist:</strong></p><ul><li></li> <li>     Beim Hochladen von Dateien kann es bei Doppelklick zu Fehlern kommen. <br /><br /><br />       Edit: lag am FILE SIZE Limit<br /><br /><br />    <br /><br /><br /></li> <li>     Date funktion Funktioniert manchmal nicht, d.h. Datum wird nicht eingestellt obwohl es eine Datumsspalte gibt. <br /><br /><br />       Edit:Bug gefunden lag am mangelndem Update in der Preview Funktion<br /><br /><br />    <br /><br /><br />  <br /></li></ul><br /><br />','<p>Wie bei jeder neuen Version fallen Fehler auf.<br /><br /><br />So auch bei dieser Version.<br /><br />Nun Ideen sind auch neue dazugekommen und ich denke mir fällt auch noch was ein.</p><p><strong>Todolist:</strong><br /><br /><br /><a href=\"https://www.marblefx.net/home/infos/show/24\">Hier</a></p><p><strong>Buglist:</strong></p><ul><li><br /></li> <li>     Beim Hochladen von Dateien kann es bei <br /><br /><br /></li></ul>','yltf','1','0','0','008.jpg','1','5.41.1','2006-09-27 15:28:00','2026-05-26 14:50:23');
