INSERT INTO `blogs` VALUES ('5','1','191','2008-01-07 20:16:00','2','MCS 1.59 workin','1','<p>Wir sind am Arbeiten was MCS 1.59 angeht.<br /><br />\neine Komplette Hilfe, neue Administration und ein paar Gimmicks wie<br /><br />\nPrivate Messages kommen alle noch in dieses Release mit rein</p><br />\n<p>fieser Bug in der Welcome gefunden und gelöst</p><br />\n','<p>Wir sind am Arbeiten was MCS 1.59 angeht.<br /><br />\neine Komplette Hilfe, neue Administration und ein paar Gimmicks wie<br /><br />\nPrivate Messages kommen alle noch in dieses Release mit rein</p><br />\n<p>fieser Bug in der Welcome gefunden und gelöst</p><br />\n','ylpb','1','0',NULL,'008.jpg','1',NULL,'2008-01-07 19:16:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('6','1','190','2008-01-14 08:02:00','3','PalivaRedesign','1','<p>Schon wieder ne durchzechte Nacht wegen ner Website,<br /><br />\nis irgendwie fast wie ne Sucht, die ganze Zeit zu Programmieren während andere Schlummern.<br /><br />\naber es hat einen Vorteil, wenn andere Wach werden sehen sie Resultate<br /><br />\nund das über Nacht.</p><br />\n<p>Und wann kommt endlich mein c\'T Abo an ?</p><br />\n','<p>Schon wieder ne durchzechte Nacht wegen ner Website,<br /><br />\nis irgendwie fast wie ne Sucht, die ganze Zeit zu Programmieren während andere Schlummern.<br /><br />\naber es hat einen Vorteil, wenn andere Wach werden sehen sie Resultate<br /><br />\nund das über Nacht.</p><br />\n<p>Und wann kommt endlich mein c\'T Abo an ? </p><br />\n','y4p5','1','0',NULL,'008.jpg','1',NULL,'2008-01-14 07:02:00','2025-02-25 13:00:24');
