INSERT INTO `blogs` VALUES ('9','1','187','2008-02-17 09:56:00','3','Is schon irre was man so macht','1','<p>Rotten Psychos ist für mich eine der besten Zeiten gewesen die ich hatte.<br /><br />\nDamals war DSL noch Teuer und man freute sich über jedes 1on1<br /><br />\nnun ist DSL billig und man hat keins weils dann doch finanzell nicht hinhaut</p><br />\n','<p>Rotten Psychos ist für mich eine der besten Zeiten gewesen die ich hatte.<br /><br />\nDamals war DSL noch Teuer und man freute sich über jedes 1on1<br /><br />\nnun ist DSL billig und man hat keins weils dann doch finanzell nicht hinhaut</p><br />\n','yvfb','1','0',NULL,'008.jpg','1',NULL,'2008-02-17 08:56:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('10','1','186','2008-11-28 09:27:00','1','How Tough - Rotten-Psychos online','1','<p>Herzlichste Gr?sse aus Bim?hlen w?nscht euch euer Asario.<br /><br />\nh?re grad ma wieder Musik und denke mir, was geht bei euch so ab.<br /><br />\nZur Zeit feile ich an der Neuen <a target=\"rotte\" href=\"http://www.rotten-psychos.de\">Rotten Psychos Seite</a> und das RP-Forum ist fast fertig.<br /><br />\nDas Forum ist eine Eigenentwicklung auf MCS Basis.<br /><br />\nHat mich ne menge Zeit gekostet bis alles so funktionierte wie gedacht.<br /><br />\nAber ich habs geschafft die Fehler die sich versteckt hatten zu finden.</p><br />\n','<p>Herzlichste Gr?sse aus Bim?hlen w?nscht euch euer Asario.<br /><br />\nh?re grad ma wieder Musik und denke mir, was geht bei euch so ab.<br /><br />\nZur Zeit feile ich an der Neuen <a target=\"rotte\" href=\"http://www.rotten-psychos.de\">Rotten Psychos Seite</a> und das RP-Forum ist fast fertig.<br /><br />\nDas Forum </p><br />\n','y2in','1','0',NULL,'008.jpg','1',NULL,'2008-11-28 08:27:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('11','1','185','2010-01-10 08:41:00','1','How Real','1','<p>Es ist mal wieder eine neue Seite fertig geworden.<br /><br />\nunter <a href=\"http://www.freundeskreis-spiegelbild.de\">www.freundeskreis-spiegelbild.de</a> findet ihr alles zum Förderverein Freundeskreis Spiegelbild</p><br />\n','<p>Es ist mal wieder eine neue Seite fertig geworden.<br /><br />\nunter <a href=\"http://www.freundeskreis-spiegelbild.de\">www.freundeskreis-spiegelbild.de</a> findet ihr alles zum Förderverein Freundeskreis Spiegelbild</p><br />\n','ytsi','1','0',NULL,'008.jpg','1',NULL,'2010-01-10 07:41:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('12','1','184','2010-01-12 15:09:00','2','MCS 1.61 workin','1','<p>Marble Content System ist in version 1.61 erschienen.<br /><br />\nNeue Navigation neues Rechtesystem und etliche Zugaben sind ins Release eingeflossen.</p><br />\n<p>weitere infos zu MCS und dem aktuellen Status auf <a target=\"marbl\" href=\"http://www.marblefx.de\">www.marblefx.de</a></p><br />\n','<p>Marble Content System ist in version 1.61 erschienen.<br /><br />\nNeue Navigation neues Rechtesystem und etliche Zugaben sind ins Release eingeflossen.</p><br />\n<p>weitere infos zu MCS und dem aktuellen Status auf <a target=\"marbl\" href=\"http://www.marblefx.de\">www.marblefx.de</a></p><br />\n','ypse','1','0',NULL,'008.jpg','1',NULL,'2010-01-12 14:09:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('13','1','183','2010-06-19 16:31:00','1','Happy Birthday Asario','1','<p>Herzlichen Glückwunsch Lieber Asario zum 27. Geburtstag.<br /><br />\nDer Tag war schön und das Wetter ging auch in Ordnung.<br /><br />\nFreue mich schon auf den Sommer.<br /><br />\nHabe nette Sachen geschenk bekommen und demnächst lad ich noch 1-2 Fineliner-Bilder hoch.<br /><br />\nHabt Spass, in liebe euer Asario.</p><br />\n','<p>Herzlichen Glückwunsch Lieber Asario zum 27. Geburtstag.<br /><br />\nDer Tag war schön und das Wetter ging auch in Ordnung.<br /><br />\nFreue mich schon auf den Sommer.<br /><br />\nHabe nette Sachen geschenk bekommen und demnächst lad ich noch 1-2 Fineliner-Bilder hoch.<br /><br />\nHabt Spass, in liebe euer Asario. </p><br />\n','yu51','1','0',NULL,'008.jpg','1',NULL,'2010-06-19 14:31:00','2025-02-25 13:00:24');
