INSERT INTO `blogs` VALUES ('19','1','177','2011-07-29 12:30:00','2','MCS Update steht bevor....','1','<p>Also hier mal wieder ein paar News aus der Devlog Ecke.<br /><br />\nDie Entwicklung von MCS 1.64 ist angelaufen....<br /><br />\nGeplant sind einige nette Features zwecks Private Messaging.<br /><br />\nUnter anderem soll ein komplettes Einstellungstool das Private Messaging noch einfacher machen.<br /><br />\nweitere Infos demnächst Hier...</p><br />\n','<p>Also hier mal wieder ein paar News aus der Devlog Ecke.<br /><br />\nDie Entwicklung von MCS 1.64 ist angelaufen....<br /><br />\nGeplant sind einige nette Features zwecks Private Messaging.<br /><br />\nUnter anderem soll ein komplettes Einstellungstool das Private Messaging noch einfacher machen.<br /><br />\nweitere Infos demnächst Hier... </p><br />\n','ykf1','1','0',NULL,'008.jpg','1',NULL,'2011-07-29 10:30:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('20','1','175','2011-08-11 13:38:00','2','news from MCS','1','<p>Private Nachrichten werden ab jetzt auf Wunsch an die eigene E-Mailadresse gesendet,<br /><br />\nso das niemand eine PM verpasst.<br /><br />\nDas Einstellungstool sowie das Profilwerkzeug werden ab demnächst zusammengefasst<br /><br />\nund in Asarios Blog implementiert.<br /><br />\n(ich arbeite noch dran)...</p><br />\n','<p>Private Nachrichten werden ab jetzt auf Wunsch an die eigene E-Mailadresse gesendet,<br /><br />\nso das niemand eine PM verpasst.<br /><br />\nDas Einstellungstool sowie das Profilwerkzeug werden ab demnächst zusammengefasst<br /><br />\nund in Asarios Blog implementiert.<br /><br />\n(ich arbeite noch dran)... </p><br />\n','yuvo','1','0',NULL,'008.jpg','1',NULL,'2011-08-11 11:38:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('21','1','176','2011-08-11 13:38:00','2','MCS version 1.67 Released','1','<p>Viele neue Features und Funktionen kommen zum Major Release von MCS.<br /><br />\nNun ist es endlich möglich mehrere MCS Instanzen auf einer Scriptbasis zu Hosten.</p><br />\n<p>Module basierendes Admincenter gehört ebenso dazu wie eine Semantic Web Funktion.</p><br />\n<p>MCS ist jetzt Multilanguage fähig.</p><br />\n<p>Vieles Neues kam dazu, altes wurde verbessert.</p><br />\n','<p>Viele neue Features und Funktionen kommen zum Major Release von MCS.<br /><br />\nNun ist es endlich möglich mehrere MCS Instanzen auf einer Scriptbasis zu Hosten.</p><br />\n<p>Module basierendes Admincenter gehört ebenso dazu wie eine Semantic Web Funktion.</p><br />\n<p>MCS ist jetzt Multilanguage fähig.</p><br />\n<p>Vieles Neues kam dazu, altes </p><br />\n','y8gh','1','0',NULL,'008.jpg','1',NULL,'2011-08-11 11:38:00','2025-02-25 13:00:24');
