INSERT INTO `blogs` VALUES ('35','1','161','2013-06-23 15:37:00','2','MCS v. 1.68 released','1','<p>Willkommen in Asarios Blog, meinem Blog auf MCS Basis.<br /><br />\nMCS version 1.68 (Honkey Donkey) wurde installiert.</p><br />\n<p>Zu den Features zählen:<br /><br />\n-Neue Icons im Admincenter<br /><br />\n-Benutzerinhalte Funktionen<br /><br />\nsowie mehrere kleine eliminierte Fehler</p><br />\n<p>Mehr Informationen im Changelog auf www.marblefx.de</p><br />\n','<p>Willkommen in Asarios Blog, meinem Blog auf MCS Basis.<br /><br />\nMCS version 1.68 (Honkey Donkey) wurde installiert.</p><br />\n<p>Zu den Features zählen:<br /><br />\n-Neue Icons im Admincenter<br /><br />\n-Benutzerinhalte Funktionen<br /><br />\nsowie mehrere kleine eliminierte Fehler</p><br />\n<p>Mehr Informationen im Changelog auf www.marblefx.de </p><br />\n','ybzf','1','0',NULL,'008.jpg','1',NULL,'2013-06-23 13:37:00','2025-02-25 13:00:24');
