INSERT INTO `blogs` VALUES ('41','1','155','2014-03-02 17:04:00','2','MCS v. 1.69 Online','1','<p>Marble Content System wurde auf Version 1.69 aktualisiert.<br /><br />\nNeben vielen kleinen Bugs die beseitigt wurden, gab es auch einige Neuentwicklungen<br /><br />\nzu bestaunen. Ein Newsletter Service sowie eine Dynamische Hilfe wurden hinzugefügt.<br /><br />\nAußerdem wurde das Suchindex Script überarbeitet sowie einige kleine Funktionen fanden den Weg ins 1.69er Release.<br /><br />\nWenn euch was auffällt schreibt mir auf www.marblefx.net/Kontakt<br /><br />\nIch wünsche euch viel Spass auf meinen Seiten.</p><br />\n<p>Asario</p><br />\n','<p>Marble Content System wurde auf Version 1.69 aktualisiert.<br /><br />\nNeben vielen kleinen Bugs die beseitigt wurden, gab es auch einige Neuentwicklungen<br /><br />\nzu bestaunen. Ein Newsletter Service sowie eine Dynamische Hilfe wurden hinzugefügt.<br /><br />\nAußerdem wurde das Suchindex Script überarbeitet sowie einige kleine </p><br />\n','y4ri','1','0',NULL,'008.jpg','1',NULL,'2014-03-02 16:04:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('42','1','154','2014-03-31 13:07:00','1','Ausstellung in Kaltenkirchen','1','<p>Am letztem Donnerstag wurde in Kaltenkirchen eine Ausstellung des Malerateliers eröffnet. Bei ca. 40 geladenen Gästen im Beratungszentrum am Flottkamp 13b in Kaltenkirchen wurde über Kunst in der Psychatrie gesprochen sowie auf einzelne Künstler eingegangen.</p><br />\n<p>Die Ausstellung läuft noch 6 Wochen und es sind etliche Künstler des Malerateliers zu sehen und auch zu Kaufen was \"wir\" alles so gemalt und kreiert haben.<br /><br />\nÃâffnungszeiten sind montags bis donnerstags von 8:30 Uhr bis 18 Uhr sowie freitags von 8:30 Uhr bis 16:00 Uhr</p><br />\n<p>Von mir sind 3 Kunstwerke ausgestellt welche das sind seht Ihr wenn ihr da seid ;)<br /><br />\nVon Hier aus noch mal Danke an Chris die das alles möglich gemacht hat.;)</p><br />\n','<p>Am letztem Donnerstag wurde in Kaltenkirchen eine Ausstellung des Malerateliers eröffnet. Bei ca. 40 geladenen Gästen im Beratungszentrum am Flottkamp 13b in Kaltenkirchen wurde über Kunst in der Psychatrie gesprochen sowie auf einzelne Künstler eingegangen.</p><br />\n<p>Die Ausstellung läuft noch 6 Wochen und es sind </p><br />\n','yayq','1','0',NULL,'ausstellung.png','1',NULL,'2014-03-31 11:07:00','2025-02-25 13:00:24');
