INSERT INTO `blogs` VALUES ('47','1','149','2014-10-19 13:29:00','3','Mein neues Bike','1','<p>Ich hab mal wieder etwas Geld in die Hand genommen und mir ein Trekking Rad zugelegt.<br /><br />\nEs fährt sich echt g**l. Hubertus, mein neues Fahrrad ist ne Granate mit Hydraulikbremsen, Federgabel, 24 Gang Schaltung, Felgendyamo, stabiler Gepäckträger und Kunststoffschutzbleche sowie jede Menge Fahrspaß inklusive.</p><br />\n<p>Ich bin Stolz auf dieses tolle Teil.</p><br />\n','<p>Ich hab mal wieder etwas Geld in die Hand genommen und mir ein Trekking Rad zugelegt.<br /><br />\nEs fährt sich echt g**l. Hubertus, mein neues Fahrrad ist ne Granate mit Hydraulikbremsen, Federgabel, 24 Gang Schaltung, Felgendyamo, stabiler Gepäckträger und Kunststoffschutzbleche sowie jede Menge Fahrspaß </p><br />\n','y2v8','1','0',NULL,'Hubertus.JPG','1',NULL,'2014-10-19 11:29:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('48','1','148','2014-10-25 12:14:00','2','MCS v. 1.70 released','1','<p>Die Neueste MCS Version ist Nr. 1.70.<br /><br />\nIn diesem Release wurde einiges neu gemacht.<br /><br />\nDas File Upload Center hat ein großes Update erfahren, so das sich Uploads parallel anstoßen lassen.<br /><br />\nAusserdem hat man im File Upload Center die Möglichkeit den Fortschritt des Uploads zu sehen.<br /><br />\nMehr infos siehe Changelog<br /><br />\nIch hoffe Ihr habt eure Freude an diesem Release.</p><br />\n','<p>Die Neueste MCS Version ist Nr. 1.70.<br /><br />\nIn diesem Release wurde einiges neu gemacht.<br /><br />\nDas File Upload Center hat ein großes Update erfahren, so das sich Uploads parallel anstoßen lassen.<br /><br />\nAusserdem hat man im File Upload Center die Möglichkeit den Fortschritt des Uploads zu sehen.<br /><br />\nMehr infos siehe Changelog  </p><br />\n','yj58','1','0',NULL,'008.jpg','1',NULL,'2014-10-25 10:14:00','2025-02-25 13:00:24');
