INSERT INTO `blogs` VALUES ('50','1','146','2014-11-16 15:49:00','3','Mein erster Ritt...','1','<p>In meinem Urlaub war ich das erste mal in meinem Leben \"selbständig\" Reiten,<br /><br />\nEs macht Irre Spaß, ist aber doch gewöhnungsbedürftig sprich ich habe Respekt vor dem Tier.</p><br />\n<p>Rispe, unser Therapiepferd ist sehr ruhig, nur an meiner Körperspannung muss ich noch arbeiten.</p><br />\n<p>PS: Reiten ist Geil ;)</p><br />\n','<p>In meinem Urlaub war ich das erste mal in meinem Leben \"selbständig\" Reiten,<br /><br />\nEs macht Irre Spaß, ist aber doch gewöhnungsbedürftig sprich ich habe Respekt vor dem Tier.</p><br />\n<p>Rispe, unser Therapiepferd ist sehr ruhig, nur an meiner Körperspannung muss ich noch arbeiten.</p><br />\n<p>PS: Reiten ist Geil ;) </p><br />\n','y57i','1','0',NULL,'Horseriding.jpg','1',NULL,'2014-11-16 14:49:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('51','1','145','2014-12-05 16:30:00','1','Frohe Weihnachten und einen...','1','<p>guten Rutsch ins neue Jahr.<br /><br />\nAnfang Dezember hat unser Chef uns zum schmunzeln gebracht.<br /><br />\nEr hat den Coca Cola Truck inkl. Weihnachtsmann zu uns bestellt. Das war ein großes Event und viel Spaß für uns.<br /><br />\nIch wünsche allen Besuchern ein sinnliches Fest und einen guten Rutsch ins neue Jahr.<br /><br />\nViele Grüße aus Bad Segeberg, Bimöhlen und Potsdam, Asario</p><br />\n','<p>guten Rutsch ins neue Jahr.<br /><br />\nAnfang Dezember hat unser Chef uns zum schmunzeln gebracht.<br /><br />\nEr hat den Coca Cola Truck inkl. Weihnachtsmann zu uns bestellt. Das war ein großes Event und viel Spaß für uns.<br /><br />\nIch wünsche allen Besuchern ein sinnliches Fest und einen guten Rutsch ins neue Jahr.<br /><br />\nViele Grüße aus Bad </p><br />\n','yr0n','1','0',NULL,'coca2.jpg','1',NULL,'2014-12-05 15:30:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('52','1','144','2015-03-20 15:49:00','1','Der Frühling kommt.','1','<p>Wie Ihr auf dem Bild seht ist schon wieder alles Grün.<br /><br />\nIn den letzten Monaten habe ich ein paar Bilder Online gestellt.<br /><br />\nIhr findet Sie wie immer über den Roten Button rechts oben auf dieser Seite.<br /><br />\nIch hoffe Ihr genießt das wunderbare Wetter wie ich letztens beim Eisessen in Bad Bramstedt.</p><br />\n<p>Ach ja, unter Mindblog gibt es ne Geschichte über mich und mein Leben.<br /><br />\nPart I ist Online, Part II kommt demnächst<br /><br />\nViele Grüße aus dem sonnigen Bimöhlen, euer Asario</p><br />\n','<p>Wie Ihr auf dem Bild seht ist schon wieder alles Grün.<br /><br />\nIn den letzten Monaten habe ich ein paar Bilder Online gestellt.<br /><br />\nIhr findet Sie wie immer über den Roten Button rechts oben auf dieser Seite.<br /><br />\nIch hoffe Ihr genießt das wunderbare Wetter wie ich letztens beim Eisessen in Bad Bramstedt.</p><br />\n<p>Ach ja, unter </p><br />\n','yle5','1','0',NULL,'spring2015.jpg','1',NULL,'2015-03-20 14:49:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('53','1','143','2015-03-20 15:51:00','0','Asario\'s Geschichte Part I','1','<p>Alles fing mit einem verkorksten 16. Geburtstag an.<br /><br />\nIch fuhr mit dem Rad durch die Gegend um mich abzureagieren und da traf ich sie wieder.<br /><br />\nEs waren die Punks vom See mit Ihren Hunden.<br /><br />\nIch spielte mit den Hunden und kam ins Gespräch-<br /><br />\nWir redeten über meinen Geburtstag und Sie fragten mich ob ich nicht mit in Ihre Kneipe kommen würde.<br /><br />\nIch sagte zu. Von da an war ich öfter in der Kneipe. Es waren verständnisvolle Menschen die völlig natürlich und nett waren. Ich fühlte mich geborgen bei Ihnen.</p><br />\n<p>Nicht so wie bei meinen Eltern, wo nur Ehe-Krach und Scheidungsstreitigkeiten an der Tagesordnung waren.<br /><br />\nWenn ein Mensch Geborgenheit sucht und nichts ausser zerrütteter Verhältnisse bekommt sucht man sich immer einen Ruhepol.<br /><br />\nDen hatte ich in dieser besagten Kneipe gefunden. Viele Hunde, nette Menschen und Party Party Party war das was ich da hatte.</p><br />\n<p>Die Partys waren eine gute Möglichkeit mich abzulenken. Ich trank ein Paar Bier und schon ging es mir viel Besser.<br /><br />\nZwar war das Gefühl nur für einen Moment vorhanden aber ich hatte meinen Spaß.</p><br />\n<p>Meine Leistungen in der Schule gingen rapide Bergab. Ich hatte einfach keine Lust es meinen Eltern Recht zu machen und in der Schule aufzupassen.<br /><br />\nIch entwickelte mich immer mehr von einem guten Schüler zu einen Klassenclown.<br /><br />\nWIeso sollte ich meinem Traum vom Meeresbiologen denn weiter Träumen wenn meine Eltern es nicht mal schaffen zusammenzuhalten ?</p><br />\n<p>Ich war frustriert und Lustlos von all dem ganzen Zeug.<br /><br />\nNur meine Punkerfreunde waren für mich da und machten mir Mut das irgendwann Licht am Ende des Tunnels sei.</p><br />\n<p>Ich hatte eine Zweite Familie gefunden.</p><br />\n<p>to be continued</p><br />\n','<p>Alles fing mit einem verkorksten 16. Geburtstag an.<br /><br />\nIch fuhr mit dem Rad durch die Gegend um mich abzureagieren und da traf ich sie wieder.<br /><br />\nEs waren die Punks vom See mit Ihren Hunden.<br /><br />\nIch spielte mit den Hunden und kam ins Gespräch-<br /><br />\nWir redeten über meinen Geburtstag und Sie fragten mich ob ich nicht mit </p><br />\n','yjwu','2','0',NULL,'008.jpg','1',NULL,'2015-03-20 14:51:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('54','1','142','2015-03-20 15:55:00','2','MCS v. 1.72 Veröfentlicht','1','<p>Joa, hab mal wieder ne neue Version released.<br /><br />\nhinzugekommen sind:</p><br />\n<ul><br />\n<li>ein neues Anti Spam Modul</li>\n<li>Sicherheitsfunktionen die bei Erhöhtem Aufkommen die Seite sperren.</li>\n<li>Signatureinstellungen automatisiert.</li>\n</ul><br />\n<p>Außerdem habe ich Fehler beseitigt im</p><br />\n<ul><br />\n<li>Benutzerprofil</li>\n<li>Meta Tags Scripts</li>\n<li>Searching Scripts</li>\n</ul><br />\n<p>sowie mehrere kleine Bugs im System.</p><br />\n','<p>Joa, hab mal wieder ne neue Version released.<br /><br />\nhinzugekommen sind:</p><br />\n<ul><br />\n<li>ein neues Anti Spam Modul</li>\n<li>Sicherheitsfunktionen die bei Erhöhtem Aufkommen die Seite sperren.</li>\n<li>Signatureinstellungen automatisiert.</li>\n</ul><br />\n<p>Außerdem habe ich Fehler beseitigt im</p><br />\n<ul><br />\n<li>Benutzerprofil</li>\n<li>Meta Tags Scripts</li>\n<li>Searching </li>\n</ul><br />\n','yo0x','1','0',NULL,'008.jpg','1',NULL,'2015-03-20 14:55:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('55','1','141','2015-05-05 12:16:00','1','Elke ist tod. :(','1','<p>Leider mussten wir Elke unsere Admin Katze einschläfern weil Sie zu aggressiv wurde und meine Eltern mehrfach gebissen hat. Sie hatte es die letzten Jahre wirklich gut bei meinen Eltern und wir hoffen das es Ihr im Himmel besser geht als hier auf der Erde.<br /><br />\nSie hatte schon immer einen leichten Schaden, nur weil es nicht besser wurde und meine Mutter mit Entzündingen schon des öfteren bei Ãârzten war, ließen wir Sie Einschläfern...<br /><br />\nR.I.P. Elke, wir denken an dich.</p><br />\n','<p>Leider mussten wir Elke unsere Admin Katze einschläfern weil Sie zu aggressiv wurde und meine Eltern mehrfach gebissen hat. Sie hatte es die letzten Jahre wirklich gut bei meinen Eltern und wir hoffen das es Ihr im Himmel besser geht als hier auf der Erde.<br /><br />\nSie hatte schon immer einen leichten Schaden, nur weil </p><br />\n','yy7a','1','0',NULL,'elke_history.jpg','1',NULL,'2015-05-05 10:16:00','2025-02-25 13:00:24');
