INSERT INTO `blogs` VALUES ('59','1','137','2015-08-04 12:13:00','3','Haare AB!','1','<p>Wie man auf dem linken Bild sieht sind meine Haare sehr kaputt gewesen.<br /><br />\nSomit nahm sich eine Mitarbeiterin bei uns die Schere und killte 25cm von meinem Haupthaar.</p><br />\n<p>Endlich wieder ohne Schmerzen kämmen und mehr Substanz.<br /><br />\nNaja, muss man sich noch dran gewöhnen... ;)<br /><br />\nAber es sieht schon besser aus.</p><br />\n','<p>Wie man auf dem linken Bild sieht sind meine Haare sehr kaputt gewesen.<br /><br />\nSomit nahm sich eine Mitarbeiterin bei uns die Schere und killte 25cm von meinem Haupthaar.</p><br />\n<p>Endlich wieder ohne Schmerzen kämmen und mehr Substanz.<br /><br />\nNaja, muss man sich noch dran gewöhnen... ;)<br /><br />\nAber es sieht schon besser aus. </p><br />\n','ycvp','1','0',NULL,'haircut.jpg','1',NULL,'2015-08-04 10:13:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('60','1','136','2015-08-30 14:26:00','1','Ricklinger Jahresfest 2015','1','<p>Auch dieses Jahr am ersten Sonntag im September findet in Ricklingen das Jahresfest statt.<br /><br />\nEs sind einige Bilder und Lampen von mir im Maleratelier zu finden.<br /><br />\nWünsche viel Spaß mit Essen, Trinken und dem restlichem Rahmenprogramm beim Fest.</p><br />\n<p>also bis Sonntag, euer Asario</p><br />\n','<p>Auch dieses Jahr am ersten Sonntag im September findet in Ricklingen das Jahresfest statt.<br /><br />\nEs sind einige Bilder und Lampen von mir im Maleratelier zu finden.<br /><br />\nWünsche viel Spaß mit Essen, Trinken und dem restlichem Rahmenprogramm beim Fest.</p><br />\n<p>also bis Sonntag, euer Asario </p><br />\n','yjgd','1','0',NULL,'jahresfest.jpg','1',NULL,'2015-08-30 12:26:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('61','1','135','2015-09-06 13:29:00','2','MCS v. 1.85 ist eingetroffen....','1','<p>Mal wieder wurde MCS erneuert.<br /><br />\nDazu gekommen sind einige kosmetische Eingriffe vorgenommen worden.<br /><br />\nEinige Formularelemente wurden mit Material Design aktualisiert.<br /><br />\nDazu kommen noch etliche Bugfixes in mehreren Komponenten.</p><br />\n<p>Hinzugekommen sind ein Datei-Synchronisations-Script um schneller neue Dateien zum Hochladen in die Update Ordner zu schieben.</p><br />\n<p>Außerdem ist ein interner Chat entstanden.</p><br />\n<p>wünsche viel Spaß mit MCS v. 1.85 ;)<br /><br />\nPS.: Momentan arbeite ich an der Integration von JQuery UI Elementen in das Admin Center.<br /><br />\nsee you soon, Paule aka Asario</p><br />\n','<p>Mal wieder wurde MCS erneuert.<br /><br />\nDazu gekommen sind einige kosmetische Eingriffe vorgenommen worden.<br /><br />\nEinige Formularelemente wurden mit Material Design aktualisiert.<br /><br />\nDazu kommen noch etliche Bugfixes in mehreren Komponenten.</p><br />\n<p>Hinzugekommen sind ein Datei-Synchronisations-Script um schneller neue Dateien </p><br />\n','ym1n','1','0',NULL,'008.jpg','1',NULL,'2015-09-06 11:29:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('62','1','134','2015-09-15 12:44:00','1','Neue Shortstories','1','<p>Hab mal wieder nen paar Shortstories<br /><br />\nhochgeladen. Ich will mal hoffen das<br /><br />\neuch die gefallen.<br /><br />\nPS: JQuery UI hält Einzug in MCS. weitere Infos demnächst im Devlog.</p><br />\n','<p>Hab mal wieder nen paar Shortstories<br /><br />\nhochgeladen. Ich will mal hoffen das<br /><br />\neuch die gefallen.<br /><br />\nPS: JQuery UI hält Einzug in MCS. weitere Infos demnächst im Devlog.</p><br />\n','yd8i','1','0',NULL,'short_st.jpg','1',NULL,'2015-09-15 10:44:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('63','1','133','2015-10-04 14:03:00','2','Neuerungen dank JQuery UI','1','<p>JQuery UI ist fast komplett integriert und ich habe kaum noch sachen zu machen... Habe jetzt alle Tabs auf den Seiten durch JQuery UI tabs ersetzt.</p><br />\n<p>Ist irgendwie irre was man so mach wenn man viel Zeit hat. War ein ganz schöner Krampf die Tabs einzubauen.<br /><br />\nIch musste alles was auf einzelnen extra Seiten war auf eine Seite reduzieren und die Verlinkung anpassen.</p><br />\n<p>Aber alles in allem hat es sich gelohnt. Sieht Jetzt Stylischer aus und geht alles sehr viel schneller.<br /><br />\nHab natürlich beim proggen etliche Bugs verursacht die ich mühsam finden und beseitigen musste.</p><br />\n<p>Ein nettes Schmankerl ist auch die neue Shortstories Seite.</p><br />\n<p>aber jetzt müsste eigentlich alles funken. wenn euch noch was auffällt schreibt mir ne PM oder mailt mir einfach über das Mailformular.</p><br />\n<p>Ach ja, Die Hilfe Seite hab ich komplett neu geschrieben und dabei ca. 80 Zeilen Code eingespart. Klingt nicht nach viel aber bei einem Vergleichsweise kleinem Script ist das schon ne Menge.</p><br />\n<p>PS: In den Privaten Nachrichten sind Smilies mit dabei.</p><br />\n<p>Bis Bald Asario.</p><br />\n','<p>JQuery UI ist fast komplett integriert und ich habe kaum noch sachen zu machen... Habe jetzt alle Tabs auf den Seiten durch JQuery UI tabs ersetzt.</p><br />\n<p>Ist irgendwie irre was man so mach wenn man viel Zeit hat. War ein ganz schöner Krampf die Tabs einzubauen.<br /><br />\nIch musste alles was auf einzelnen extra Seiten war auf </p><br />\n','y5hp','1','0',NULL,'008.jpg','1',NULL,'2015-10-04 12:03:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('64','1','132','2015-10-13 12:50:00','1','JQuery UI integrated','1','<p>Ich hab mir Erlaubt, JQuery UI in meine Seite zu integrieren.<br /><br />\nsichtbar ist das in den Private Messages. Ich habe die Bereiche mit Tabs modernisiert.<br /><br />\nHat ne Menge Zeit gekostet bis alles funktionierte aber es ist geschafft.<br /><br />\nHoffe euch gefallen die Akzente die ich mit JQuery UI gesetzt habe.<br /><br />\nAnsonsten ist noch alles Banane in Big Bad Bottermilk Bimöhlen.</p><br />\n','<p>Ich hab mir Erlaubt, JQuery UI in meine Seite zu integrieren.<br /><br />\nsichtbar ist das in den Private Messages. Ich habe die Bereiche mit Tabs modernisiert.<br /><br />\nHat ne Menge Zeit gekostet bis alles funktionierte aber es ist geschafft.<br /><br />\nHoffe euch gefallen die Akzente die ich mit JQuery UI gesetzt habe.<br /><br />\nAnsonsten </p><br />\n','ymq1','1','0',NULL,'jquery.jpg','1',NULL,'2015-10-13 10:50:00','2025-02-25 13:00:24');
