INSERT INTO `blogs` VALUES ('74','1','122','2016-05-24 12:50:00','2','MCS Version 1.98 erschienen','1','<p>Joa, hab mal wieder n paar Aktualisierung an MCS vorgenommen.</p><br />\n<ol><br />\n<li>Semantische Tags wurden eingeführt, basierend auf dem Suchindex.</li>\n<li>Countpixel zur Besucheranalyse wurden integriert.</li>\n<li>Sitemap wurde eingebaut und auf einigen Seiten aktiviert.</li>\n<li>Bilderupload Script wurde um Standardgrößen für einzelne Galerien erweitert,<br /><br />\nd.h. je nach gewählter Galerie sind unterschiedliche Standardgrößen einstellbar</li>\n</ol><br />\n','<p>Joa, hab mal wieder n paar Aktualisierung an MCS vorgenommen.</p><br />\n<ol><br />\n<li>Semantische Tags wurden eingeführt, basierend auf dem Suchindex.</li>\n<li>Countpixel zur Besucheranalyse wurden integriert.</li>\n<li>Sitemap wurde eingebaut und auf einigen Seiten aktiviert.</li>\n<li>Bilderupload Script wurde um Standardgrößen für </li>\n</ol><br />\n','y5qo','1','0',NULL,'008.jpg','1',NULL,'2016-05-24 10:50:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('75','1','121','2016-06-14 13:04:00','1','Diverse neue Bilder','1','<p>Ich habe mal wieder Bilder hochgeladen.<br /><br />\nIhr findet die Objekte unter <a href=\"/home/pictures\">Bilder</a><br /><br />\nIch wünsche euch viel Spaß damit.<br /><br />\nFalls Ihr immer noch nicht wisst wie man zu den Bildern kommt so guggt doch mal ganz nach oben. Auf dem Schwarzen Balken ist die Navigation zum Surfen.<br /><br />\nIch wünsche euch viel Spaß auf meiner Seite.<br /><br />\nBis bald, Asario.</p><br />\n','<p>Ich habe mal wieder Bilder hochgeladen.<br /><br />\nIhr findet die Objekte unter <a href=\"/home/pictures\">Bilder</a><br /><br />\nIch wünsche euch viel Spaß damit.<br /><br />\nFalls Ihr immer noch nicht wisst wie man zu den Bildern kommt so guggt doch mal ganz nach oben. Auf dem Schwarzen Balken ist die Navigation zum Surfen.<br /><br />\nIch wünsche euch viel Spaß </p><br />\n','ykp0','1','0',NULL,'dune2016.jpg','1',NULL,'2016-06-14 11:04:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('76','1','120','2016-06-28 12:57:00','2','MCS Version 2.01','1','<p>Herzlich Willkommen bei MCS 2.01 mit 201 Bildern unter Images. Jetzt endlich mit kanonischen URLs. Nun kann man z.B. mit www.asario,de/shortstories die Shortstories aufrufen. Hinzugekommen zu 2 neuen Bildern ist auch 1 Shortstory,<br /><br />\nAlles im Sinne von 2.01 ;)<br /><br />\nWünsche viel Spass, Asario</p><br />\n','<p>Herzlich Willkommen bei MCS 2.01 mit 201 Bildern unter Images. Jetzt endlich mit kanonischen URLs. Nun kann man z.B. mit www.asario,de/shortstories die Shortstories aufrufen. Hinzugekommen zu 2 neuen Bildern ist auch 1 Shortstory,<br /><br />\nAlles im Sinne von 2.01 ;)<br /><br />\nWünsche viel Spass, Asario </p><br />\n','yhpt','1','0',NULL,'11new_noname.jpg','1',NULL,'2016-06-28 10:57:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('77','1','119','2016-07-04 11:12:00','2','Neuerungen in MCS 2.01','1','<p>Es ist mal wieder was von der MCS Front zu berichten.<br /><br />\nZu diesem Major Release habe ich Kanonische also eindeutige und einfachere URL\'s eingebaut,<br /><br />\nnoch ein paar Bugs in der Gallery Connection gekillt und die Countpixel Module gefixt.<br /><br />\nIch musste wegen den Kanonischen URL\'s fast die gesamte Verlinkung und die Verknüpfung<br /><br />\nder Bilder erneuern/reparieren.<br /><br />\nEben ist mir bzw Mumbo ein Fehler beim PM Script aufgefallen den ich ebenso gefixt hab.<br /><br />\nSinn und zweck der Kanonischen URL\'s ist es den Seitennamen zu vereinfachen/zu verkürzen.<br /><br />\nSo wird aus www.asario.de/blogs -> www.asario.de/blogs was für Suchmaschinen<br /><br />\nideal ist und auch leichter zu merken ist.<br /><br />\nBin zwar noch nicht zufrieden mit den Kanonischen URL\'s aber da fällt mir auch noch was ein.<br /><br />\nHoffe Ihr habt Spaß auf meinen Seiten...<br /><br />\nin Love Asario</p><br />\n','<p>Es ist mal wieder was von der MCS Front zu berichten.<br /><br />\nZu diesem Major Release habe ich Kanonische also eindeutige und einfachere URL\'s eingebaut,<br /><br />\nnoch ein paar Bugs in der Gallery Connection gekillt und die Countpixel Module gefixt.<br /><br />\nIch musste wegen den Kanonischen URL\'s fast die gesamte Verlinkung und die </p><br />\n','y5nu','1','0',NULL,'008.jpg','1',NULL,'2016-07-04 09:12:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('78','1','118','2016-07-08 14:14:00','3','Burzeltach und seine Folgen...','1','<p>Wie Ihr vielleicht wisst hatte ich am 18.06. Geburtstag.<br /><br />\nund habe mir selber ein großes Geschenk gemacht.<br /><br />\nIch habe eine nicht nennenswerte Summe Geld investiert und<br /><br />\nmir einen absolut bequemen Schreibtischsessel gekauft. (siehe Bild)<br /><br />\nAuf dem Foto ist hoffentlich mein 2tes großes Geschenk zu sehen.<br /><br />\nEin Pinsel-Set zum professionellem Malen im Maleratelier und bei mir zu Hause.<br /><br />\nDemnächst ist Mighty Crab Online (Unter <a href=\"/home/show/pictures/Ausgemaltes\">www.asario.de/home/show/pictures/Ausgemaltes</a> bald zu sehen)<br /><br />\nDenn das Zen-Color Buch von meiner Schwester ist mit guten Motiven gespickt, so das ich hin und wieder mal was ausmale und unter <a href=\"/home/show/pictures/Ausgemaltes\">Bilder->Ausgemaltes</a> veröffentliche.</p><br />\n','<p>Wie Ihr vielleicht wisst hatte ich am 18.06. Geburtstag.<br /><br />\nund habe mir selber ein großes Geschenk gemacht.<br /><br />\nIch habe eine nicht nennenswerte Summe Geld investiert und<br /><br />\nmir einen absolut bequemen Schreibtischsessel gekauft. (siehe Bild)<br /><br />\nAuf dem Foto ist hoffentlich mein 2tes großes Geschenk zu </p><br />\n','yho5','1','0',NULL,'Desk-Star-Painter.jpg','1',NULL,'2016-07-08 12:14:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('79','1','117','2016-07-08 14:16:00','0','Asario\'s Geschichte Part II','1','<p>So da wÃÆären wir nun.<br /><br />\nWir haben eine zerÃÆüttet Familie, ein Haufen Chaoten und jede Menge Party.<br /><br />\nIch blieb bei meinem Vater nachdem meine Mutter Ihn verlassen hatte.<br /><br />\nAber auch das ging nicht lange gut. Nach 2-3 Jahren bei meinem Vater zog ich dann doch zu meiner Mutter.</p><br />\n<p>Ich fing eine Ausbildung zum Kaufmann fÃÆür Audiovisuelle Medien an und nach 1,5 Jahren ging ich nicht mehr hin, weil mir alles zu viel wurde.<br /><br />\nIrgendwann quartierte mich meine Mutter aus und ich zog in ein Neubauviertel in Potsdam.</p><br />\n<p>Nach anderthalb Jahren im \"RattenkÃÆäfig\" fing bei mir alles an sich zu ÃÆändern. Ich bekam komische Nachrichten per Telepathie und zog mich immer weiter ZurÃÆück.<br /><br />\nIn Wahrheit bekam ich eine Psychose und wurde Psychisch Krank.</p><br />\n<p>Schizophrenie die Diagnose der ÃÆÃ¢â¬Å¾rzte schockte mich schon ganz schÃÆön.<br /><br />\nDie ersten Jahre mit der Krankheit dachte ich ich wÃÆähr gesund nur irgendwann wurde mir klar das man diese Krankheit zwar beherrschen aber nicht heilen kann.</p><br />\n<p>So nun bin ich halt krank, na und ?<br /><br />\nIch versuche das Beste draus zu machen und bin seit ein paar Jahren ziemlich stabil.</p><br />\n<p>to be continued...</p><br />\n','<p>So da wÃÆären wir nun.<br /><br />\nWir haben eine zerÃÆüttet Familie, ein Haufen Chaoten und jede Menge Party.<br /><br />\nIch blieb bei meinem Vater nachdem meine Mutter Ihn verlassen hatte.<br /><br />\nAber auch das ging nicht lange gut. Nach 2-3 Jahren bei meinem Vater zog ich dann doch zu meiner Mutter.</p><br />\n<p>Ich fing eine Ausbildung zum </p><br />\n','yjeh','2','0',NULL,'008.jpg','1',NULL,'2016-07-08 12:16:00','2025-12-07 10:25:23');
INSERT INTO `blogs` VALUES ('80','1','116','2016-08-24 04:20:00','1','Neue Galerie vorhanden.','1','<p>Ich habe ja wie bereits erwähnt ein Ausmalbuch \"Zen Colour Ocean\" zum Geburtstag<br /><br />\nbekommen. Hier und jetzt könnt Ihr meine Werke bewundern.<br /><br />\nViel Spaß, Asario</p><br />\n','<p>Ich habe ja wie bereits erwähnt ein Ausmalbuch \"Zen Colour Ocean\" zum Geburtstag<br /><br />\nbekommen. Hier und jetzt könnt Ihr meine Werke bewundern.<br /><br />\nViel Spaß, Asario</p><br />\n','y7s4','1','0',NULL,'Zen_Coloured.jpg','1',NULL,'2016-08-24 02:20:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('81','1','115','2016-10-08 14:07:00','2','Neuerungen unter der Haube','1','<p>Mal wieder habe ich geschraubt und gemacht um MCS noch besser zu machen.<br /><br />\nUnter der Haube habe ich eine Synchronisationsumgebung gebaut um noch einfacher neue Inhalte zu publizieren.<br /><br />\nWenn ich also bei mir zu Hause Dateien oder Datenbankinhalte verändere bzw Erstelle so synchronisiert MCS alle Inhalte auf meinen Webspace.<br /><br />\nSomit muss ich mich nicht mit Datenbank Dumps rumärgern und habe alle Seiten immer aktuell. Momentan schraube ich noch am RSS-Feed, der irgendwie noch nicht mit dem Sync-Client kompatibel scheint.<br /><br />\nAber gut ding will Weile haben, oder wie man auch sagt: Was lange Wert, wird endlich gut.<br /><br />\nIn diesem Sinne, Have Fun Folks.</p><br />\n','<p>Mal wieder habe ich geschraubt und gemacht um MCS noch besser zu machen.<br /><br />\nUnter der Haube habe ich eine Synchronisationsumgebung gebaut um noch einfacher neue Inhalte zu publizieren.<br /><br />\nWenn ich also bei mir zu Hause Dateien oder Datenbankinhalte verändere bzw Erstelle so synchronisiert MCS alle Inhalte auf meinen </p><br />\n','y1cm','1','0',NULL,'17new_noname.jpg','1',NULL,'2016-10-08 12:07:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('82','1','114','2016-12-19 15:24:00','1','Merry X-Mas','1','<p>Ich wünsche allen Fans ein besinnliches und schönes Weihnachtsfest und einen guten Rutsch ins neue Jahr. Hoffen wir das wir auch im nächsten Jahr alles Glück der Welt haben und Fit sind wie im Letzten Jahr.</p><br />\n<p>Viele Grüße aus Bimöhlen, Berlin und Potsdam wünscht euer Asario.</p><br />\n','<p>Ich wünsche allen Fans ein besinnliches und schönes Weihnachtsfest und einen guten Rutsch ins neue Jahr. Hoffen wir das wir auch im nächsten Jahr alles Glück der Welt haben und Fit sind wie im Letzten Jahr.</p><br />\n<p>Viele Grüße aus Bimöhlen, Berlin und Potsdam wünscht euer Asario. </p><br />\n','y3ek','1','0',NULL,'xmas2k16._4.jpg','1',NULL,'2016-12-19 14:24:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('83','1','113','2017-01-25 06:37:00','1','Big Exceptions','1','<p>Die Erwartung ist groß, ich hoffe sie enttäuscht euch nicht.<br /><br /><br /><br />Hab mal wieder was ausgemalt, zu finden unter <a href=\"/home/show/pictures/Ausgemaltes\"> BIlder->Ausgemaltes</a> und ich arbeite an einem neuen Acryl auf Leinwand Bild was demnächst hier reinflattern wird.<br /><br /><br /><br />ich hoffe Ihr mögt Quallen, denn mein aktuellstes Werk heißt Jellyfish, hat aber im Grunde genommen keine Ähnlichkeit mit einer Qualle.<br /><br /><br /><br />Ach ja, vielleicht ist es euch schon Aufgefallen, Ich habe ein paar Layout Änderungen unter <strong>Images</strong>, <strong>Devlog</strong>, <strong>Mindblog</strong> und <strong>Shortstories</strong> vorgenommen. Ich hoffe Ihr mögt es..<br /><br /><br /><br />PS: Die Bewertung von Bildern habe ich etwas verändert, aber lasst euch davon nicht abschrecken zu Voten...<br /><br /><br /><br />Ach ja, bevor ichs vergesse, MCS wurde auf Version 2.15 gepatcht.<br /><br /><br /><br />enjoy the ride, Asario</p>','<p>Die Erwartung ist groß, ich hoffe sie enttäuscht euch nicht.<br /><br /><br /><br />Hab mal wieder was ausgemalt, zu finden unter Bilder->Ausgemaltes und ich arbeite an einem neuen Acryl auf Leinwand Bild was demnächst hier reinflattern wird.<br /><br /><br /><br />ich hoffe Ihr mögt Quallen, denn mein aktuellstes Werk heißt Jellyfish, hat aber im </p>','yf80','1','0','1','jelly.jpg','1','5.41.1','2017-01-25 05:37:00','2026-05-28 15:11:43');
INSERT INTO `blogs` VALUES ('84','1','112','2017-01-25 08:17:00','2','MCS Version 2.15','1','<p>Sooooooooooooo, mal wieder was neues aus meinen Programmiergriffeln.<br /><br /></p><p>MCS 2.15 wurde veröffentlicht. In Diesem Release ist fast alles von und mit Google.<br />Ein Sitemap Generator wurde ebenso integriert wie ein Rich Snippet Modul.<br /><br /></p><p>Google mein Freund ist fleißig am Crawlen der Seiten. Außerdem hab ich einige kleinere Updates vorgenommen. Unter anderem habe ich ein paar Bugs im Synchro-Tool beseitigt.<br />Ich muss demnächst noch die RSS-Feeds kontrollieren, hab dazu bis jetzt noch keine Zeit gehabt.<br />Auch dieses mal wünsche ich eine schöne Zeit auf meinem Blog.<br />mfg Asario</p>','<p>Sooooooooooooo, mal wieder was neues aus meinen Programmiergriffeln.<br /><br /><br />MCS 2.15 wurde veröffentlicht. In Diesem Release ist fast alles von und mit Google.<br /><br /><br />Ein Sitemap Generator wurde ebenso integriert wie ein Rich Snippet Modul.<br /><br /><br />Google mein Freund ist fleißig am Crawlen der Seiten. Außerdem hab ich einige </p>','y2co','1','0','0','008.jpg','1',NULL,'2017-01-25 07:17:00','2025-12-11 10:32:05');
INSERT INTO `blogs` VALUES ('85','1','111','2017-01-29 12:48:00','1','MCS Points - die Smarte Währung','1','<p>Ab jetzt könnt ihr als registrierte Benutzer satte Prämien kassieren wenn ihr genug Artikel kommentiert, Newsletter lest, Shortpoems vorschlagt oder Bilder bewertet. Für jede Aktion gibt es Punkte die Ihr gegen Bilder, eintauschen könnt. Ihr erhaltet signierte original Kunstwerke für eure Butze oder zum Verschenken.</p><br />\n<p>{{ premium_fx() }}</p><br />\n','<p>Ab jetzt könnt ihr als registrierte Benutzer satte Prämien kassieren wenn ihr genug Artikel kommentiert, Newsletter lest, Shortpoems vorschlagt oder Bilder bewertet. Für jede Aktion gibt es Punkte die Ihr gegen Bilder, eintauschen könnt. Ihr erhaltet signierte original Kunstwerke für </p><br />\n','y80y','1','0',NULL,'153new_noname.jpg','1',NULL,'2017-01-29 11:48:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('86','1','110','2017-02-19 10:37:00','3','Meine Privaten News','1','<p>Ich überlege zur Zeit was ich mir von meinem Ersparten kaufen soll / möchte.<br /><br />\nMeine Grafikkarte röhrt seit einigen Wochen, ich werde sie wohl ersetzen müssen.<br /><br />\nDiesmal wird es wohl eine karte von NVIDIA sein.<br /><br />\nschon falls ich es doch noch mal schaffe mich an Linux zu gewöhnen.<br /><br />\nAußerdem sind die Nvidia Karten Sparsamer was den Energieverbrauch angeht.<br /><br />\nWird wohl ne GF1060 werden. Mein Kollege Mumbo hat mir die schon empfohlen.<br /><br />\nNun ja Eine neue Grafikkarte soll auch 4k-Fähig sein, falls ich mir noch nen 4k Monitor holen will.<br /><br />\nDie sind zwar jetzt noch zu Teuer aber die Preise fallen mit der Zeit bekanntlich so dass sie bald erschwinglich sind.<br /><br />\nNun ja alles klar auf der Andrea Doria.<br /><br />\nEs ist schon Praktisch das die Dinger im Leerlauf die Lüfter anhalten können.<br /><br />\nSo hab ich beim Programmieren von Websites immer einen leisen PC.<br /><br />\nSchade das AMD und Linux nicht so ganz Harmonieren, hätte mir gern ne AMD Karte geholt.<br /><br />\nAber man soll an die Zukunft denken.</p><br />\n<p>Ach ja ich vergas doch glatt das ich mir ne Blu-Ray über Amy Winehouse gekauft habe.<br /><br />\nIst echt Irre, was die so erlebt hat.<br /><br />\nR.I.P. Amy.</p><br />\n<p>in diesem Sinne, Viel Spaß Asario</p><br />\n','<p>Ich überlege zur Zeit was ich mir von meinem Ersparten kaufen soll / möchte.<br /><br />\nMeine Grafikkarte röhrt seit einigen Wochen, ich werde sie wohl ersetzen müssen.<br /><br />\nDiesmal wird es wohl eine karte von NVIDIA sein.<br /><br />\nschon falls ich es doch noch mal schaffe mich an Linux zu gewöhnen.<br /><br />\nAußerdem sind die Nvidia Karten </p><br />\n','yya7','2','0',NULL,'008.jpg','1',NULL,'2017-02-19 09:37:00','2025-02-25 13:00:24');
