INSERT INTO `blogs` VALUES ('89','1','107','2017-03-24 15:50:00','1','MultiLanguageSupport','1','<p>Ab jetzt könnt ihr einige der Seiten in Englischer Sprache sehen.<br /><br />\nDie gesamten Texte konnte ich noch nicht einenglischen aber Einstellungen und Backend sind Multi-Lang fähig. Einstellen der Sprache könnt ihr in der Navigation oben rechts.</p><br />\n<p>Ich habe grad einen üblen Bug im Dateihochladescript gefunden...<br /><br />\nmüsste jetzt wieder gehen.</p><br />\n<p>Wünsche viel Spaß damit. falls euch noch was einfällt oder auffällt schreibt es mir.</p><br />\n<p>Kommentare, E-Mails oder PMs sind willkommen...<br /><br />\nbis denne, Asario</p><br />\n','<p>Ab jetzt könnt ihr einige der Seiten in Englischer Sprache sehen.<br /><br />\nDie gesamten Texte konnte ich noch nicht einenglischen aber Einstellungen und Backend sind Multi-Lang fähig. Einstellen der Sprache könnt ihr in der Navigation oben rechts.</p><br />\n<p>Ich habe grad einen üblen Bug im Dateihochladescript gefunden...<br /><br />\nmüsste </p><br />\n','yezi','1','0',NULL,'15new_noname.jpg','1',NULL,'2017-03-24 14:50:00','2025-02-25 13:00:24');
