INSERT INTO `blogs` VALUES ('91','1','105','2017-05-26 03:13:00','2','Die Version 2.35 von MCS wurde aktualisiert.','1','<p>Mal wieder habe ich eine neue Version veröffentlicht.<br /><br /><br /><br />Die größte Änderung betrifft die Übersicht der Tabelle.<br /><br /><br /><br />Hier kann man nun per Drag & Drop Einträge sortieren.<br /><br /><br /><br />Einige Styles von www.marblefx.de wurden überarbeitet, so dass alle Ränder genau übereinander liegen.<br /><br /><br /><br />Außerdem habe ich diverse Bugs in einigen Modulen gestopft.<br /><br /><br /><br />Ein übler Bug im Kontaktformular wurde soeben gefixt.<br /><br /><br /><br />Ihr könnt mir wieder Mails schreiben...<br /><br /><br /><br />mehr Infos wie immer im Changelog.</p>','<p>Mal wieder habe ich eine neue Version veröffentlicht.<br /><br /><br /><br />Die größte Änderung betrifft die Übersicht der Tabelle.<br /><br /><br /><br />Hier kann man nun per Drag & Drop Einträge sortieren.<br /><br /><br /><br />Einige Styles von www.marblefx.de wurden überarbeitet, so dass alle Ränder genau übereinander liegen.<br /><br /><br /><br />Außerdem habe ich diverse Bugs in einigen </p>','yyhr','1','0','1','008.jpg','1','5.47.9','2017-05-26 01:13:00','2026-06-02 08:40:17');
