INSERT INTO `blogs` VALUES ('102','1','94','2017-10-14 13:08:00','1','Mein Praktikum','1','<p>Ich habe letzten Freitag mein Praktikum bei Elan Nord beendet. Die Arbeit macht mir sehr viel Spaß und ich konnte einiges lernen sowie ausprobieren. Ich durfte viel mit Klebefolien arbeiten und bekam Einblicke in die Arbeit eines Mediengestalters.<br /><br />\nIch bin sehr froh das ich dieses Praktikum machen konnte, und freue mich auf ein Wiedersehen mit dem Team von Elan Nord.</p><br />\n','<p>Ich habe letzten Freitag mein Praktikum bei Elan Nord beendet. Die Arbeit macht mir sehr viel Spaß und ich konnte einiges lernen sowie ausprobieren. Ich durfte viel mit Klebefolien arbeiten und bekam Einblicke in die Arbeit eines Mediengestalters.<br /><br />\nIch bin sehr froh das ich dieses Praktikum machen konnte, und freue mich </p><br />\n','yvow','1','0',NULL,'40new_noname.jpg','1',NULL,'2017-10-14 11:08:00','2025-02-25 13:00:24');
