INSERT INTO `blogs` VALUES ('111','1','85','2018-04-18 13:32:00','2','Frickeleien am Code','1','<p>Habe auch dieses mal einiges verbessert.<br /><br />\nIm Fokus stand die Google XML Scriptsammlung. Hier war einiges im argen aber ich konnte es richten, so das Google nur noch geänderte Seiten aktualisieren muss.<br /><br />\nHab ne Menge Hirnschmalz verbraucht um alles zum laufen zu bringen.</p><br />\n<p>Aber es ist geschafft und ich bin Stolz auf meine Arbeit in die ich meine Feierabende investiert habe.</p><br />\n<p>Hoffe Ihr genießt das schöne Wetter.<br /><br />\nIch geh jetzt raus mich sonnen.</p><br />\n<p>GRTZ from Bimöhlen, Asario</p><br />\n','<p>Habe auch dieses mal einiges verbessert.<br /><br />\nIm Fokus stand die Google XML Scriptsammlung. Hier war einiges im argen aber ich konnte es richten, so das Google nur noch geänderte Seiten aktualisieren muss.<br /><br />\nHab ne Menge Hirnschmalz verbraucht um alles zum laufen zu bringen.</p><br />\n<p>Aber es ist geschafft und ich bin Stolz </p><br />\n','ybj2','1','0',NULL,'008.jpg','1',NULL,'2018-04-18 11:32:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('112','1','84','2018-04-20 12:20:00','3','Ein bisschen leer hier','1','<p>Hab lange nix mehr hier rein geschrieben.<br /><br />\nIch genieße das schöne Wetter in SH.<br /><br />\nSonne Satt und das im April, fast wie letztes Jahr.</p><br />\n<p>Momentan plane ich Umbauarbeiten an MCS die ich bis zum Sommer 2018 abgeschloßen haben möchte.</p><br />\n<p>Ist nur Organisatorischer Kram, aber der muss auch sein.</p><br />\n<p>Bin echt zufrieden mit meiner Neuanschaffung, einer LUMIX TZ-71.<br /><br />\ndas Studium des Handbuches steht auch noch auf meiner TODO-Liste.</p><br />\n<p>Bin jetzt bei Seite 98 von 300. Aber ein paar Kamerafeatures sind echt gut.<br /><br />\nMit freundlichen Grüßen, Asario</p><br />\n','<p>Hab lange nix mehr hier rein geschrieben.<br /><br />\nIch genieße das schöne Wetter in SH.<br /><br />\nSonne Satt und das im April, fast wie letztes Jahr.</p><br />\n<p>Momentan plane ich Umbauarbeiten an MCS die ich bis zum Sommer 2018 abgeschloßen haben möchte.</p><br />\n<p>Ist nur Organisatorischer Kram, aber der muss auch sein.<br /><br />\n</p><br />\n','y0p7','1','0',NULL,'008.jpg','1',NULL,'2018-04-20 10:20:00','2025-02-25 13:00:24');
