INSERT INTO `blogs` VALUES ('120','1','75','2018-08-10 14:02:00','1','Neue Fotos und neue MCS Version','1','<p>Ich habe unter Photos neue Bilder hochgeladen und gleichzeitig eine neue MCS Version installiert.<br /><br />\nIst ein grosses Release geworden, mit vielen Verbesserungen.<br /><br />\nAm Newsletter arbeite ich noch... da steckt noch Potenzial drin.<br /><br />\nWeitere Infos siehe Devlog oder im Changelog auf www.marblefx.de/changelog</p><br />\n','<p>Ich habe unter Photos neue Bilder hochgeladen und gleichzeitig eine neue MCS Version installiert.<br /><br />\nIst ein grosses Release geworden, mit vielen Verbesserungen.<br /><br />\nAm Newsletter arbeite ich noch... da steckt noch Potenzial drin.<br /><br />\nWeitere Infos siehe Devlog oder im Changelog auf www.marblefx.de/changelog </p><br />\n','yit8','1','0',NULL,'71new_noname.jpg','1',NULL,'2018-08-10 12:02:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('121','1','74','2018-08-23 11:11:00','2','Neues PM Layout, Stats und MCS-Newsletter','1','<p>Habe am Layout der PM\'s in Asarios Blog gearbeitet.<br /><br />\nDas Backend ist jetzt auch im MCS 2.87 Layout gestyled<br /><br />\nHat mich ne Menge Arbeit gekostet, fügt sich jetzt aber besser ins Gesamtbild ein.</p><br />\n<p>Der fleißige Newsletterleser kommt jetzt zu Punkten.<br /><br />\nIn Jedem neuen Newsletter steckt ein Link mit dem sich ab sofort MCS-Points sammeln lassen.</p><br />\n<p>Musste deswegen auch die Statistiken erweitern</p><br />\n<p>Außerdem hab ich seit den letzten news mal wieder ein paar Did You Know Fragen geupped.<br /><br />\nHope you enjoy it, Asario</p><br />\n','<p>Habe am Layout der PM\'s in Asarios Blog gearbeitet.<br /><br />\nDas Backend ist jetzt auch im MCS 2.87 Layout gestyled<br /><br />\nHat mich ne Menge Arbeit gekostet, fügt sich jetzt aber besser ins Gesamtbild ein.</p><br />\n<p>Der fleißige Newsletterleser kommt jetzt zu Punkten.<br /><br />\nIn Jedem neuen Newsletter steckt ein Link mit dem sich ab sofort </p><br />\n','yeub','1','0',NULL,'72new_noname.jpg','1',NULL,'2018-08-23 09:11:00','2025-02-25 13:00:24');
