INSERT INTO `blogs` VALUES ('135','1','60','2019-05-27 05:16:00','1','Besuch bei meinem kleinem Neffen','1','<p>Ich habe letztes Wochenende zum ersten mal meinen Neffen im Arm halten können.<br /><br />\nEcht süß der kleine Racker. Alfred, so heißt er ist ein echt süßes Baby.<br /><br />\nMit einem Kampfgewicht von 4290 g und einer Körperlänge von 56 cm war das ein ganz schöner Brocken. Aber er ist gesund und munter, was die Hauptsache ist.</p><br />\n<p>Außerdem habe ich ein Wallpaper mit Alfred verschönert.<br /><br />\nUnd ich habe die Prämien verändert. Viele Artworks sind jetzt mit noch weniger Punkten zu haben. Viel Spaß beim posten & bewerten.</p><br />\n','<p>Ich habe letztes Wochenende zum ersten mal meinen Neffen im Arm halten können.<br /><br />\nEcht süß der kleine Racker. Alfred, so heißt er ist ein echt süßes Baby.<br /><br />\nMit einem Kampfgewicht von 4290 g und einer Körperlänge von 56 cm war das ein ganz schöner Brocken. Aber er ist gesund und munter, was die Hauptsache ist.  </p><br />\n','y0lx','1','0',NULL,'100new_noname.jpg','1',NULL,'2019-05-27 03:16:00','2025-02-25 13:00:24');
