INSERT INTO `blogs` VALUES ('155','1','40','2022-06-19 09:15:00','1','3D Printer Objekte','1','<p>Happy Birthday to me.<br /><br />\nHabe meinen 3D Drucker in Betrieb genommen und mal was Künstlerisches gedruckt.<br /><br />\nEs ist ein Relief erstellt und mit PLA gedruckt worden.<br /><br />\nDer Druck dauerte zwar fast 3 Stunden, aber es hat sich gelohnt, wie ich finde.</p><br />\n<p>Hope you enjoy, Asario</p><br />\n','<p>Happy Birthday to me.<br /><br />\nHabe meinen 3D Drucker in Betrieb genommen und mal was Künstlerisches gedruckt.<br /><br />\nEs ist ein Relief erstellt und mit PLA gedruckt worden.<br /><br />\nDer Druck dauerte zwar fast 3 Stunden, aber es hat sich gelohnt, wie ich finde.</p><br />\n<p>Hope you enjoy, Asario </p><br />\n','yhtg','1','0',NULL,'dragonbird.jpg','1',NULL,'2022-06-28 16:00:00','2025-02-25 13:00:24');
