INSERT INTO `blogs` VALUES ('161','1','35','2023-02-13 06:56:00','1','Frohe Ostern 2023','1','<p>Ostern ist eine Zeit der Erneuerung, der Freude und der Hoffnung, und in diesem Jahr ist es ein besonders bedeutungsvolles Fest, da wir die Herausforderungen des vergangenen Jahres hinter uns lassen und in eine bessere Zukunft blicken.<br /><br />\nIn diesem Sinne, Frohe Ostern, Asario</p><br />\n','<p>Ostern ist eine Zeit der Erneuerung, der Freude und der Hoffnung, und in diesem Jahr ist es ein besonders bedeutungsvolles Fest, da wir die Herausforderungen des vergangenen Jahres hinter uns lassen und in eine bessere Zukunft blicken.<br /><br />\nIn diesem Sinne, Frohe Ostern, Asario </p><br />\n','y3yl','1','1',NULL,'132new_noname.jpg','1',NULL,'2023-02-13 05:56:00','2025-02-25 13:00:24');
INSERT INTO `blogs` VALUES ('162','1','34','2023-02-22 13:10:00','1','Frühling','1','<p>Das Ende des Winters bringt eine Veränderung mit sich, da der Schnee zu schmelzen beginnt und die Natur aus dem Winterschlaf erwacht. Die Temperaturen werden wärmer und die Tage länger.<br /><br />\nIch hoffe ich komme bald mal wieder nach Eekholdt, weil es dort schön ist wenn die Sonne zu scheinen beginnt. AuÃ?erdem ist Eekholdt gleich um die Ecke und immer einen Besuch wert.</p><br />\n','<p>Das Ende des Winters bringt eine Veränderung mit sich, da der Schnee zu schmelzen beginnt und die Natur aus dem Winterschlaf erwacht. Die Temperaturen werden wärmer und die Tage länger.<br /><br />\nIch hoffe ich komme bald mal wieder nach Eekholdt, weil es dort schön ist wenn die Sonne zu scheinen beginnt. </p><br />\n','y2wj','1','1',NULL,'149new_noname.jpg','1',NULL,'2023-02-22 12:10:00','2025-02-25 13:00:24');
