INSERT INTO `image_categories` VALUES ('1','1','1','38','5','3DDrucker','3DPrinter','Frisch aus dem 3D Drucker','3DPrinter','3dprinter.jpg','3D Druck Bilder','<p>Alles was man so mit einem 3D Drucker machen kann.</p><br />','2022-01-05 10:51:56','2025-06-05 19:48:20','1');
INSERT INTO `image_categories` VALUES ('2','1','2','17','3','acryl','acryl','Bilder mit Acrylfarbe auf Leinwand','Acryl','acryl_new.jpg','Acryl Bilder','<p>All diese Bilder sind mit Acrylfarbe entstanden. Meist skizziere ich alles mit Bleistift, male dann mit Permanent Marker die Linien nach und male dann das Bild mit Acryl Farbe aus. Man muss sich ganz schön konzentrieren das man sich nicht vermalt. </p><p>Die Arbeitszeit ist je nach Größe unterschiedlich, da die Farbe teilweise erst noch trocknen muss.</p>','2016-11-30 18:49:02','2025-12-29 16:26:42','1');
INSERT INTO `image_categories` VALUES ('3','1','3','39','1','alphabet','alphabet','Von A-Z - Eine Auswahl ausgewählter Fotos','Alphabet','abc.jpg','Alphabetische Bilder','<p>Ich suche nach Buchstaben in Photos, hier sind meine Schnappschüsse dazu zu finden.</p><p>Es ist ganz schön knifflig passende Bilder zu finden. Aber man findet hin und wieder mal was passendes...</p>','2016-11-30 19:54:48','2025-12-11 10:52:24','0');
INSERT INTO `image_categories` VALUES ('4','1','4','41','3','ausgemaltes','ausgemaltes','Ausgemalte Bilder von Asario','Ausgemaltes','ausgemalt.jpg','Ausgemaltes','<p>Ausmalbilder für Erwachsene sind voll im kommen. Hier ein paar Werke die ich mit Fineliner bzw. Acrylfarbe ausgemalt habe. Das größte Problem sind die feinen Strukturen in den Vorlagen.</p><p>Momentan arbeite ich aus 4 Büchern heraus nette Grafiken. Ich erwähne in der Beschreibung das Quellbuch der Bilder.</p>','2016-12-13 19:37:07','2025-12-11 10:53:16','1');
INSERT INTO `image_categories` VALUES ('5','1','5','40','1','digital','digital','Meine Wallpaper','Digital','digital.jpg','Digitale Kunstwerke','<p>Hier findet Ihr ein paar Wallpaper von mir. Wallpaper entstehen bei mir oft als Zufallobjekt beim Spielen mit Grafiken. Alle Wallpaper könnt ihr in Originalgröße runterladen. Einfach aufs Thumbnail rechtsklicken und \"Bild Speichern\" oder so ähnlich auswählen.</p><p>Ich hoffe euch gefallen meine kleinen Experimente.</p>','2017-02-03 19:52:03','2025-12-11 10:53:46','0');
INSERT INTO `image_categories` VALUES ('6','1','6','14','2','fasermaler','fasermaler','Mit Filzstift auf Pappe und Papier oder Leinwand','Fasermaler','faser.jpg','Fasermaler Bilder','<p>Filzstift und Edding auf Karton / Pappe / Leinwand.<br />diese Bilder sind so Ähnlich wie Fineliner oder Acryl nur das sie auf Pappe bzw. Papier oder Leinwand entstande<br />sind und nur mit Filzstift und Edding ausgemalt worden.<br />Die Bilder sind doppelt so groß wie Fineliner Pix und auch mit doppelt so dicken Stiften gemalt. </p>','2016-12-13 19:45:20','2025-12-11 15:22:42','1');
INSERT INTO `image_categories` VALUES ('7','1','7','43','2','fineliner','fineliner ','Meine Fineliner Kunstwerke','Fineliner','fineliner.jpg','Fineliner Galerie','<p>Fineliner Artworks von mir.<br />Das sind meine Fineliner Bilder von 2003-fx_year()<br />Ja ich liebe meine Stabilo Fineliner <img src=\"/images/smilies/icon_wink.gif\" class=\"inline\" alt=\"icon_wink.gif\" />.</p>','2018-06-09 20:22:00','2025-12-11 10:54:55','1');
INSERT INTO `image_categories` VALUES ('8','1','11','57','8','portraits','portraits','Portraits','Portraits','lampen.png','Portraits Hauptsächlich mit Bleistift','<p>Hier sind Portraits diverser Personen vorhanden, von Prominent bis Privat</p>','2017-02-03 20:08:59','2026-07-01 17:06:24','1');
INSERT INTO `image_categories` VALUES ('9','1','12','39','1','monstarz','monstarz','Mein Monstar in der großen weiten Welt','Montstarz','monstar.jpg','Mein Monstar','<p>Ich habe vor Jahren ein Monstar-Kuscheltier bekommen, und habe es auf die Reise quer durch die Welt geschickt. Verwandte und Freunde haben das Tier in Szene gesetzt und Fotografiert.</p><p>Mein Monster in der großen weiten Welt. Shots by Chinagirl, Baxter the dog, Nitropower, mir und Maria Zinckernagel Ich finde mein Monstar extrem Fotogen.</p>','2017-02-03 20:10:18','2025-12-11 10:57:02','0');
INSERT INTO `image_categories` VALUES ('10','1','13','39','1','photos','photos','Meine gemischten Photos','Photos','photos.jpg','Fotografien','<p>Fotos aufgenommen mit diversen Kameras an verschiedenen Orten. Ostsee, Berlin, Kreis Segeberg uvm.</p>\n','2018-06-29 15:07:58','2018-06-29 15:07:58','0');
INSERT INTO `image_categories` VALUES ('11','1','14','16','2','sketches','sketches','Skizzen und Kritzeleien','Sketches','sketches.jpg','Sketches Galerie','<p>Skizzen und Entwürfe bzw. Konzeptzeichnungen sind hier.</p><p>Hauptsächlich sind es Entwürfe die diese Galerie Prägen. </p><p>Unter anderem sind es kleinere Zeichnungen die zwar fertig aber nicht Formatfüllend sind.</p><p>Auch kleinere Experimente findet Ihr hier Versammelt unter dem Dach Sketches.</p>','2017-02-03 20:14:25','2025-12-11 10:58:06','1');
INSERT INTO `image_categories` VALUES ('12','1','15','28','5','keramik','keramik','Getöpferte Dinge','Keramik','clay.jpg','getöpfertes','<p>Einige Werke sind in 3D. Ausgestellt sind getöpferte Kunstwerke von Asario.</p><p>Alles ist von mir handgemacht, mit Hilfe meines 3D-Druckers</p>','2017-05-28 16:12:44','2025-12-11 10:58:56','1');
INSERT INTO `image_categories` VALUES ('13','1','16','43','2','zentangle','zentangle','Meine Zentangle Galerie - Alles Handgetangelt','Zentangles','zia_icon.jpg','Zentangle®','<p>Meine ersten Versuche mit Zentangle Inspired Art. </p><p>Zentangles sind eigentlich Zeichnungen im Format 9x9cm, </p><p>sind sie größer heißen sie offiziell \"Zentangle Inspired Art\".</p><p>Es gibt diverse Zentangle Bücher und Hefte in denen die verschiedenen Muster abgedruckt sind, Ich habe einige davon zu Papier gebracht und unter anderem Postkarten mit diesen Mustern bemalt.</p><p>Zentangles sind zum entspannen gut und fördern die Kreativität.</p>','2017-02-03 20:15:43','2025-12-11 11:00:04','1');
INSERT INTO `image_categories` VALUES ('16','1','8','14','2','grafitti','grafitti','Grafittis','Grafitti',NULL,'grafitti','Meine Grafitti-Sammlung - Von Neu bis Alt','2026-06-29 17:46:34','2026-07-03 15:25:29','1');

DROP TABLE IF EXISTS `images`;
CREATE TABLE `images` (
  `id` bigint(11) NOT NULL AUTO_INCREMENT,
  `pub` tinyint(1) NOT NULL DEFAULT 1,
  `position` bigint(11) DEFAULT NULL,
  `image_categories_id` bigint(11) NOT NULL DEFAULT 0,
  `name` varchar(80) DEFAULT NULL,
  `status` enum('','empty','sold','forsale','unsaleable','givenaway','lost','inwork') NOT NULL DEFAULT 'empty',
  `created_at` datetime DEFAULT NULL,
  `categorie_id` bigint(11) NOT NULL DEFAULT 0,
  `type_id` bigint(11) NOT NULL DEFAULT 0,
  `img_x` bigint(11) DEFAULT NULL,
  `img_y` bigint(11) DEFAULT NULL,
  `chg_date` bigint(11) NOT NULL DEFAULT 0,
  `message` longtext DEFAULT NULL,
  `camera_id` bigint(11) NOT NULL DEFAULT 0,
  `link` varchar(255) DEFAULT NULL,
  `image_path` varchar(90) DEFAULT NULL,
  `Format` varchar(80) DEFAULT NULL,
  `preis` float(10,2) DEFAULT NULL,
  `xkis_feed` tinyint(2) NOT NULL DEFAULT 0,
  `users_id` bigint(11) NOT NULL DEFAULT 0,
  `xis_IsSaleable` tinyint(1) DEFAULT NULL,
  `xkis_Ticker` tinyint(2) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

