DROP TABLE IF EXISTS `newsletter_blacklist`;
CREATE TABLE `newsletter_blacklist` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `pub` longtext NOT NULL,
  `mail` mediumtext NOT NULL,
  `uhash` varchar(255) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `newsletter_reci`;
CREATE TABLE `newsletter_reci` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `pub` tinyint(4) NOT NULL,
  `uhash` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `nick` varchar(255) DEFAULT NULL,
  `title` varchar(255) DEFAULT NULL,
  `surname` varchar(255) DEFAULT NULL,
  `prename` varchar(255) DEFAULT NULL,
  `subscribed_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `xis_checked` tinyint(4) DEFAULT 0,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=73 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `notifications`;
CREATE TABLE `notifications` (
  `id` bigint(11) NOT NULL AUTO_INCREMENT,
  `pub` tinyint(2) NOT NULL DEFAULT 1,
  `type_ol` enum('localhost','online','both') NOT NULL DEFAULT 'localhost',
  `name` varchar(80) DEFAULT NULL,
  `text` varchar(255) DEFAULT NULL,
  `days` int(5) DEFAULT 7,
  `rights` varchar(50) DEFAULT NULL,
  `linkname` varchar(255) DEFAULT NULL,
  `status_ol` enum('points','warning','info','success') DEFAULT 'info',
  `seconds` bigint(11) NOT NULL DEFAULT 50000000,
  `url` varchar(255) DEFAULT NULL,
  `function` varchar(255) DEFAULT NULL,
  `function_link` varchar(255) DEFAULT NULL,
  `timespy` varchar(50) NOT NULL,
  `rightstocheck` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

